void sobel(const uint8_t *input, uint8_t *output, int width, int height)
{
    /* Knob Variables Declaration Start */
    float loop_perforation_factor = 1.0;  // Loop perforation (truncation)
    float precision_scale = 1.0;          // Precision scaling
    int truncate_enabled = 0;             // Truncated computations
    /* Knob Variables Declaration End */

    int perforated_height = height * loop_perforation_factor;
    int perforated_width = width * loop_perforation_factor;

    for (int y = 0; y < perforated_height; y++) {  // Loop perforation applied
        for (int x = 0; x < perforated_width; x++) {  // Loop perforation applied

            if (x == 0 || x == perforated_width - 1 || y == 0 || y == perforated_height - 1) {
                output[y * width + x] = 0;
                continue;
            }

            int p00 = input[(y-1)*width + (x-1)];
            int p01 = input[(y-1)*width +  x   ];
            int p02 = input[(y-1)*width + (x+1)];
            int p10 = input[ y   *width + (x-1)];
            int p12 = input[ y   *width + (x+1)];
            int p20 = input[(y+1)*width + (x-1)];
            int p21 = input[(y+1)*width +  x   ];
            int p22 = input[(y+1)*width + (x+1)];

            int gx = -p00 + p02 - 2*p10 + 2*p12 - p20 + p22;
            int gy =  p00 + 2*p01 + p02 - p20 - 2*p21 - p22;

            gx = (int)(gx * precision_scale);  // Precision scaling applied
            gy = (int)(gy * precision_scale);  // Precision scaling applied

            int mag;
            if (truncate_enabled) {  // Truncated computations applied
                mag = abs(gx);  // Simplified gradient magnitude
            } else {
                mag = abs(gx) + abs(gy);
            }

            if (mag > 255) mag = 255;

            output[y * width + x] = (uint8_t)mag;
        }
    }
}
